import json
import sys
import os

# Database ID for YB_Leads_Master
DB_ID = "3c1ec539-c2b9-8178-9e45-df66466a72be"

# CSV files to process
csv_files = {
    "pretoria_all_businesses.csv": "pretoria_all_businesses",
    "pretoria_businesses.csv": "pretoria_businesses",
    "pretoria_electricians_businesses.csv": "pretoria_electricians_businesses"
}

def parse_reviews(reviews_str):
    """Extract number from 'X Reviews' string"""
    if not reviews_str:
        return 0
    try:
        return int(reviews_str.split()[0])
    except:
        return 0

def parse_establishment_year(year_str):
    """Parse establishment year"""
    if not year_str:
        return None
    try:
        return int(year_str)
    except:
        return None

def build_upsert_item(row, source):
    """Build upsert item from CSV row"""
    name = row.get('Name', '').strip()
    if not name:
        return None

    # Build match criteria (by name)
    match = {"property": "Name", "equals": name}

    # Build properties
    props = {
        "Name": {"title": [{"text": {"content": name}}]},
        "Email": {"email": row.get('Email', '').strip() or None},
        "Address": {"rich_text": [{"text": {"content": row.get('Address', '').strip()}}]} if row.get('Address', '').strip() else {"rich_text": []},
        "Contact Number": {"phone_number": row.get('Contact Number', '').strip() or None},
        "Mobile Phone": {"phone_number": row.get('Mobile Phone', '').strip() or None},
        "WhatsApp": {"url": row.get('WhatsApp', '').strip() or None},
        "Website": {"url": row.get('Website', '').strip() or None},
        "Establishment Year": {"number": parse_establishment_year(row.get('Establishment Year', '').strip())} if parse_establishment_year(row.get('Establishment Year', '').strip()) else {"number": None},
        "Employees": {"select": {"name": row.get('Employees', '').strip()}} if row.get('Employees', '').strip() else {"select": None},
        "Registration Code": {"rich_text": [{"text": {"content": row.get('Registration Code', '').strip()}}]} if row.get('Registration Code', '').strip() else {"rich_text": []},
        "Company Description": {"rich_text": [{"text": {"content": row.get('Company Description', '').strip()}}]} if row.get('Company Description', '').strip() else {"rich_text": []},
        "Categories": {"multi_select": [{"name": cat.strip()} for cat in row.get('Categories', '').split(',') if cat.strip()]} if row.get('Categories', '').strip() else {"multi_select": []},
        "Reviews": {"number": parse_reviews(row.get('Reviews', '').strip())},
        "Verified": {"select": {"name": row.get('Verified', '').strip()}} if row.get('Verified', '').strip() else {"select": None},
        "Premium": {"select": {"name": row.get('Premium', '').strip()}} if row.get('Premium', '').strip() else {"select": None},
        "Q&A": {"rich_text": [{"text": {"content": row.get('Q&A', '').strip()}}]} if row.get('Q&A', '').strip() else {"rich_text": []},
        "URL": {"url": row.get('URL', '').strip() or None},
        "Source": {"select": {"name": source}},
        "Notes": {"rich_text": []}
    }

    # Remove None values for properties that don't accept them
    clean_props = {}
    for k, v in props.items():
        if k in ['Email', 'Contact Number', 'Mobile Phone', 'WhatsApp', 'Website', 'Establishment Year', 'Employees', 'Verified', 'Premium', 'URL', 'Source']:
            # These can be None/null
            if v is not None:
                clean_props[k] = v
        else:
            clean_props[k] = v

    return {
        "match": match,
        "create": {"properties": clean_props},
        "update": {"properties": clean_props}
    }

# Read all CSVs
all_items = []
base_path = "/root/projects/Yellosa Leads"

for filename, source in csv_files.items():
    filepath = os.path.join(base_path, filename)
    if not os.path.exists(filepath):
        print(f"File not found: {filepath}")
        continue

    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            item = build_upsert_item(row, source)
            if item:
                all_items.append(item)

# Split into batches of 10 (Notion API limit)
batch_size = 10
batches = [all_items[i:i+batch_size] for i in range(0, len(all_items), batch_size)]

# Write batches to files
for i, batch in enumerate(batches):
    payload = {"items": batch}
    out_file = f"/tmp/batch_{i+1}.json"
    with open(out_file, 'w') as f:
        json.dump(payload, f, indent=2)
    print(f"Batch {i+1}: {len(batch)} items -> {out_file}")

print(f"\nTotal leads: {len(all_items)}")
print(f"Batches: {len(batches)}")","path":"/root/parse_leads.py"}

